import { sql } from "drizzle-orm";
import { customType, integer, pgEnum, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Who created or last changed something: Lemy in the app (`user`), an API token (`sunday`), or the app itself
 * (`system`: worker, calendar sync). The exact token is recorded separately (`token_id` in change_log/audit_event).
 */
export const itemSourceEnum = pgEnum("item_source", ["user", "sunday", "system"]);
export type ItemSource = (typeof itemSourceEnum.enumValues)[number];

/** Primary key: UUIDv7 generated by Postgres 18; the app may also supply one (offline creates). */
export const id = () => uuid().primaryKey().default(sql`uuidv7()`);

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

/** Maintained by the `touch_updated_at` / `bump_row_version` triggers (migration 0001). */
export const updatedAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

/** `timestamptz` that may be empty. */
export const at = () => timestamp({ withTimezone: true });

/**
 * Columns of every syncable domain row. `version` and `updated_at` are set by the `bump_row_version` trigger on
 * every UPDATE (whatever the app sends), so optimistic concurrency can't be forgotten. `deleted_at` is a soft
 * delete: offline clients need the tombstone; rows are purged 30 days later.
 */
export const syncable = () => ({
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  version: integer().notNull().default(1),
  updatedBy: itemSourceEnum().notNull(),
  deletedAt: at(),
});

/** Binary column as Uint8Array in the app, Buffer for the driver. */
export const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
  dataType: () => "bytea",
  toDriver: (v) => Buffer.from(v),
  fromDriver: (v) => new Uint8Array(v),
});
